use std::collections::HashSet;

/// Removes duplicates from the input vector `nums`.
/// 
/// Postconditions:
/// 1. The result vector contains no duplicates.
/// 2. The set of elements in the result equals the set of elements in the input.
/// 
/// This implementation preserves the order of first occurrences.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut res = Vec::new();

    for &num in &nums {
        if !seen.contains(&num) {
            seen.insert(num);
            res.push(num);
        }
    }

    res
}

